<a class="btn btn-outline-secondary mb-3" href="<?= BASE_URL ?>/crm/lead?id=<?= (int)$lead['id'] ?>">Volver a consulta</a><h1 class="h3 mb-4"><?= e($title) ?></h1>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= e($success) ?></div><?php endif; ?><?php if ($errors): ?><div class="alert alert-danger" role="alert"><ul class="mb-0"><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<section class="card card-body mb-4"><p class="mb-0"><strong>Consulta #<?= (int)$lead['id'] ?>:</strong> <?= e($lead['nombres']) ?></p><?php if (isset($row['id'])): ?><p class="mt-2 mb-0"><strong>Inmueble:</strong> <?= e($row['titulo']) ?> · <?= e(Closing::TYPES[$row['tipo']]) ?> · <?= e($row['moneda']) ?></p><?php endif; ?></section>
<?php if (($row['etapa'] ?? '')==='ganada'): ?><section class="card card-body"><div class="alert alert-success">Oportunidad ganada por cierre de operación. Este registro no se puede editar.</div><p>Monto final: <?= e($row['moneda']) ?> <?= number_format((float)$row['monto_estimado'],0) ?><?= $row['tipo']==='alquiler' ? ' / mes' : '' ?> · Probabilidad: 100%</p><p style="white-space:pre-wrap"><?= e($row['notas']) ?></p><?php if ($row['cierre_id'] && in_array($user['rol'],['superadmin','admin'],true)): ?><a href="<?= BASE_URL ?>/closings/show?id=<?= (int)$row['cierre_id'] ?>">Ver cierre de operación</a><?php endif; ?></section><?php else: ?>
<form class="card card-body" method="post" action="<?= BASE_URL ?>/opportunities/save?<?= isset($row['id']) ? 'id='.(int)$row['id'] : 'lead_id='.(int)$lead['id'] ?>"><?= Csrf::field() ?><div class="row g-3">
<?php if (!isset($row['id'])): ?><div class="col-12"><label class="form-label" for="propiedad_id">Inmueble *</label><select class="form-select" id="propiedad_id" name="propiedad_id" required><option value="">Seleccionar</option><?php foreach ($properties as $property): ?><option value="<?= (int)$property['id'] ?>" <?= (int)($row['propiedad_id'] ?? 0)===(int)$property['id'] ? 'selected' : '' ?>><?= e($property['titulo']) ?> · <?= e($property['moneda']) ?> <?= number_format((float)$property['precio'],0) ?> · <?= e($property['disponibilidad']) ?></option><?php endforeach; ?></select><p class="form-text">Hasta 100 inmuebles elegibles. El inmueble asociado a la consulta se prioriza si está disponible. La moneda se toma del inmueble elegido y queda guardada en la oportunidad.</p></div><?php endif; ?>
<div class="col-md-6"><label class="form-label" for="monto_estimado">Monto estimado<?= isset($row['moneda']) ? ' ('.e($row['moneda']).')' : ' en la moneda del inmueble' ?> *</label><input class="form-control" id="monto_estimado" name="monto_estimado" type="number" inputmode="numeric" min="1" max="5000000" step="1" required value="<?= e(isset($row['monto_estimado']) && is_numeric($row['monto_estimado']) && (float)$row['monto_estimado']===floor((float)$row['monto_estimado']) ? (string)(int)$row['monto_estimado'] : ($row['monto_estimado'] ?? '')) ?>"><p class="form-text">Entero de 1 a 5 000 000. Para alquileres, indica renta mensual.</p></div><div class="col-md-6"><label class="form-label" for="probabilidad">Probabilidad estimada (%) *</label><input class="form-control" id="probabilidad" name="probabilidad" type="number" min="0" max="100" step="1" required value="<?= e((string)($row['probabilidad'] ?? '50')) ?>"></div><div class="col-12"><label class="form-label" for="etapa">Estado</label><select class="form-select" id="etapa" name="etapa"><?php foreach (['abierta','perdida','cancelada'] as $key): ?><option value="<?= e($key) ?>" <?= ($row['etapa'] ?? '')===$key ? 'selected' : '' ?>><?= e(Opportunity::STAGES[$key]) ?></option><?php endforeach; ?></select><p class="form-text">Ganada se registra automáticamente al cerrar una operación. Perdida o cancelada guarda probabilidad 0. Para reabrir, la consulta y el inmueble deben seguir siendo elegibles.</p></div><div class="col-12"><label class="form-label" for="notas">Notas</label><textarea class="form-control" id="notas" name="notas" rows="4" maxlength="4000"><?= e($row['notas'] ?? '') ?></textarea></div><div class="col-12"><button class="btn btn-primary">Guardar oportunidad</button></div></div></form><?php endif; ?>

